// M0 producer/format corpus freeze (MEET plan, M0 "Freeze a producer/format
// corpus and bandwidth benchmark fixtures"; owner decision D3 in
// retired-docs:verification/2026-09-19-owner-consolidated-decisions.md). The frozen
// manifest lives at docs/verification/meet-m0-corpus.json; the corpus bytes
// live at testdata/corpus/ and are regenerated byte-deterministically by
// scripts/gen-meet-m0-corpus.sh.
//
// This file is pure verification: it never generates corpus bytes and never
// renders anything. Two honesty rules are enforced structurally:
//
//   - synthetic-seed entries (deterministic in-repo fixtures for bandwidth
//     benchmarking) must re-derive their frozen sha256/byte-size/intrinsic
//     count from the bytes on disk — drift fails.
//   - producer-pinned entries produced by the D3-pinned LibreOffice engine
//     stay byte-absent while acquisition-pending. A file parked under a
//     pinned name before the pinned engine produced it is fabrication and is
//     refused here; synthetic seeds are never passable as producer-pinned
//     evidence.
const (
	// M0CorpusSchemaVersion is the manifest schema this file verifies.
	M0CorpusSchemaVersion = "setjoin.meet.m0-corpus/1"

	// M0CorpusClassProducerPinned marks bytes produced (or to be produced) by
	// the pinned producer engine, with the engine version captured verbatim
	// from `soffice --version` at generation time — never invented.
	M0CorpusClassProducerPinned = "producer-pinned"
	// M0CorpusClassSyntheticSeed marks deterministic in-repo generated
	// fixtures (bandwidth benchmarking, LibreOffice conversion INPUTS).
	M0CorpusClassSyntheticSeed = "synthetic-seed"

	// M0CorpusStatusFrozen marks a frozen entry whose bytes exist and are
	// pinned by digest.
	M0CorpusStatusFrozen = "frozen"
	// M0CorpusStatusAcquisitionPending marks a producer-pinned entry whose
	// bytes do not exist yet (engine capture happens on linux-ci-host per D3).
	M0CorpusStatusAcquisitionPending = "acquisition-pending"
)

// M0CorpusEntry is one frozen corpus row. Only the fields verification needs
// are typed; the manifest carries editorial sections (R2 protocol,
// qualification readiness) that verification deliberately ignores.
type M0CorpusEntry struct {
	File      string `json:"file"`
	Format    string `json:"format"`
	Class     string `json:"class"`
	Status    string `json:"status"`
	ByteSize  int64  `json:"byteSize"`
	SHA256    string `json:"sha256"`
	CountKind string `json:"countKind"`
	Count     int    `json:"count"`
	// BenchmarkRole names the R2/budget cell this fixture feeds
	// (small-deck, asset-heavy, ...); empty on pure format-coverage pins.
	BenchmarkRole string `json:"benchmarkRole,omitempty"`
	// Producer-pinned fields: the deterministic regeneration recipe and the
	// synthetic-seed entry the pinned output is produced FROM.
	Recipe      string `json:"recipe,omitempty"`
	SourceEntry string `json:"sourceEntry,omitempty"`
	Provenance  string `json:"provenance,omitempty"`
}

// M0CorpusManifest is the parsed frozen manifest header + entries.
type M0CorpusManifest struct {
	SchemaVersion string          `json:"schemaVersion"`
	CorpusID      string          `json:"corpusId"`
	Revision      int             `json:"revision"`
	FrozenAt      string          `json:"frozenAt"`
	Entries       []M0CorpusEntry `json:"entries"`
}

// ParseM0CorpusManifest parses and validates the frozen manifest. Unknown
// editorial fields are ignored by design.
func ParseM0CorpusManifest(data []byte) (*M0CorpusManifest, error) {
	m := &M0CorpusManifest{}
	if err := json.Unmarshal(data, m); err != nil {
		return nil, fmt.Errorf("m0 corpus manifest: %w", err)
	}
	if m.SchemaVersion != M0CorpusSchemaVersion {
		return nil, fmt.Errorf("m0 corpus manifest: schemaVersion %q, want %q",
			m.SchemaVersion, M0CorpusSchemaVersion)
	}
	if m.CorpusID == "" {
		return nil, errors.New("m0 corpus manifest: corpusId empty")
	}
	if _, err := time.Parse(time.RFC3339, m.FrozenAt); err != nil {
		return nil, fmt.Errorf("m0 corpus manifest: frozenAt %q: %w", m.FrozenAt, err)
	}
	if len(m.Entries) == 0 {
		return nil, errors.New("m0 corpus manifest: no entries")
	}
	seen := make(map[string]bool, len(m.Entries))
	for i := range m.Entries {
		if err := validateM0CorpusEntry(&m.Entries[i]); err != nil {
			return nil, fmt.Errorf("m0 corpus manifest entry %d: %w", i, err)
		}
		if seen[m.Entries[i].File] {
			return nil, fmt.Errorf("m0 corpus manifest: duplicate entry %q", m.Entries[i].File)
		}
		seen[m.Entries[i].File] = true
	}
	return m, nil
}

func validateM0CorpusEntry(e *M0CorpusEntry) error {
	if e.File == "" || e.File != filepath.Base(e.File) ||
		e.File == "." || e.File == ".." ||
		strings.ContainsRune(e.File, '\\') {
		return fmt.Errorf("file %q must be a bare corpus-dir filename", e.File)
	}
	switch e.Format {
	case "pdf", "pptx", "docx", "xlsx", "odp", "vtt":
	default:
		return fmt.Errorf("format %q outside the frozen producer/format set", e.Format)
	}
	switch e.Class {
	case M0CorpusClassSyntheticSeed, M0CorpusClassProducerPinned:
	default:
		return fmt.Errorf("class %q is neither %s nor %s",
			e.Class, M0CorpusClassSyntheticSeed, M0CorpusClassProducerPinned)
	}
	switch e.Status {
	case M0CorpusStatusFrozen, M0CorpusStatusAcquisitionPending:
	default:
		return fmt.Errorf("status %q is neither %s nor %s",
			e.Status, M0CorpusStatusFrozen, M0CorpusStatusAcquisitionPending)
	}
	if e.SHA256 == "" {
		// Nothing captured yet: only an acquisition-pending pinned entry may
		// be digest-less, and it must not claim bytes or counts.
		if e.Status != M0CorpusStatusAcquisitionPending {
			return fmt.Errorf("entry %q: frozen entry %s without sha256",
				e.File, e.Status)
		}
		if e.Class != M0CorpusClassProducerPinned {
			return fmt.Errorf("entry %q: %s entry without sha256 can never be verification input",
				e.File, e.Class)
		}
		if e.ByteSize != 0 || e.Count != 0 {
			return fmt.Errorf("entry %q: acquisition-pending entry claims captured bytes/counts", e.File)
		}
		return nil
	}
	if !isM0SHA256Hex(e.SHA256) {
		return fmt.Errorf("entry %q: sha256 is not 64 lowercase hex chars", e.File)
	}
	if e.ByteSize <= 0 {
		return fmt.Errorf("entry %q: frozen byteSize must be positive", e.File)
	}
	if e.Count <= 0 {
		return fmt.Errorf("entry %q: frozen count must be positive", e.File)
	}
	if e.CountKind == "" {
		return fmt.Errorf("entry %q: countKind missing", e.File)
	}
	return nil
}

// VerifyM0CorpusDir verifies a corpus directory against the parsed manifest:
// every digest-pinned entry re-derives its sha256, byte size and intrinsic
// count from the bytes on disk; every acquisition-pending producer-pinned
// name stays byte-absent; and the directory holds nothing the manifest does
// not claim. The corpus directory must exactly equal the frozen manifest.
func VerifyM0CorpusDir(corpusDir string, m *M0CorpusManifest) error {
	claimed := make(map[string]bool, len(m.Entries))
	for i := range m.Entries {
		e := &m.Entries[i]
		claimed[e.File] = true
		path := filepath.Join(corpusDir, e.File)
		if e.SHA256 == "" {
			if _, err := os.Stat(path); err == nil {
				return fmt.Errorf("m0 corpus: producer-pinned entry %s has bytes on disk before acquisition; fabricated output must never stand as pinned evidence", e.File)
			} else if !errors.Is(err, fs.ErrNotExist) {
				return fmt.Errorf("m0 corpus: entry %s: %w", e.File, err)
			}
			continue
		}
		// #nosec G304 -- path is corpusDir joined with a manifest filename that
		// ParseM0CorpusManifest has constrained to a bare base name (no path
		// separators, not "."/".."), so it cannot escape the corpus directory.
		data, err := os.ReadFile(path)
		if err != nil {
			return fmt.Errorf("m0 corpus: entry %s: %w", e.File, err)
		}
		if int64(len(data)) != e.ByteSize {
			return fmt.Errorf("m0 corpus: entry %s: byte size %d, frozen %d", e.File, len(data), e.ByteSize)
		}
		sum := sha256.Sum256(data)
		if got := hex.EncodeToString(sum[:]); got != e.SHA256 {
			return fmt.Errorf("m0 corpus: entry %s: sha256 %s, frozen %s", e.File, got, e.SHA256)
		}
		got, err := MeasureM0CorpusCount(e.Format, data)
		if err != nil {
			return fmt.Errorf("m0 corpus: entry %s: %w", e.File, err)
		}
		if got != e.Count {
			return fmt.Errorf("m0 corpus: entry %s: %s count %d, frozen %d",
				e.File, e.CountKind, got, e.Count)
		}
	}
	dirEntries, err := os.ReadDir(corpusDir)
	if err != nil {
		return fmt.Errorf("m0 corpus: corpus dir: %w", err)
	}
	for _, de := range dirEntries {
		if de.IsDir() {
			return fmt.Errorf("m0 corpus: unexpected subdirectory %q in corpus dir", de.Name())
		}
		if !claimed[de.Name()] {
			return fmt.Errorf("m0 corpus: unmanifested file %q in corpus dir", de.Name())
		}
	}
	return nil
}

// MeasureM0CorpusCount re-derives a corpus file's intrinsic count from its
// bytes: PDF pages from the page-tree object tokens, pptx slides and xlsx
// sheets from package part names, odp slides from content.xml draw:page
// elements, docx from the generator-declared docProps/app.xml <Pages>
// (DOCX has no intrinsic rendered-page count — the manifest labels this
// countKind "declared-pages"), and WebVTT cues from timing lines. It mirrors
// the measurers inside scripts/gen-meet-m0-corpus.sh; the two must agree,
// and the frozen manifest is where agreement is pinned.
func MeasureM0CorpusCount(format string, data []byte) (int, error) {
	switch format {
	case "pdf":
		// Synthetic seeds write "/Type /Page" (spaced); LibreOffice — the
		// D3 pinned producer — writes "/Type/Page" (unspaced). Both
		// spellings are counted, subtracting the page-tree token
		// ("/Type/Pages") per spelling because it contains the page token
		// as a prefix. Mirrors the measurer inside
		// scripts/gen-meet-m0-corpus.sh; the two must agree.
		return (bytes.Count(data, []byte("/Type /Page")) -
			bytes.Count(data, []byte("/Type /Pages"))) +
			(bytes.Count(data, []byte("/Type/Page")) -
				bytes.Count(data, []byte("/Type/Pages"))), nil
	case "pptx", "xlsx":
		prefix := "ppt/slides/slide"
		if format == "xlsx" {
			prefix = "xl/worksheets/sheet"
		}
		return countM0ZipParts(data, prefix)
	case "odp":
		zr, err := openM0Zip(data)
		if err != nil {
			return 0, err
		}
		content, err := m0ZipRead(zr, "content.xml")
		if err != nil {
			return 0, err
		}
		return strings.Count(string(content), "<draw:page "), nil
	case "docx":
		zr, err := openM0Zip(data)
		if err != nil {
			return 0, err
		}
		app, err := m0ZipRead(zr, "docProps/app.xml")
		if err != nil {
			return 0, err
		}
		return parseM0DeclaredPages(string(app))
	case "vtt":
		n := 0
		for _, line := range strings.Split(string(data), "\n") {
			if strings.Contains(line, "-->") {
				n++
			}
		}
		return n, nil
	default:
		return 0, fmt.Errorf("m0 corpus: no intrinsic count measurer for format %q", format)
	}
}

func countM0ZipParts(data []byte, prefix string) (int, error) {
	zr, err := openM0Zip(data)
	if err != nil {
		return 0, err
	}
	n := 0
	for _, f := range zr.File {
		if strings.HasPrefix(f.Name, prefix) &&
			strings.HasSuffix(f.Name, ".xml") &&
			!strings.Contains(f.Name, "/_rels/") {
			n++
		}
	}
	if n == 0 {
		return 0, fmt.Errorf("m0 corpus: no %s* parts in package", prefix)
	}
	return n, nil
}

func openM0Zip(data []byte) (*zip.Reader, error) {
	zr, err := zip.NewReader(bytes.NewReader(data), int64(len(data)))
	if err != nil {
		return nil, fmt.Errorf("not a readable zip-based corpus file: %w", err)
	}
	return zr, nil
}

func m0ZipRead(zr *zip.Reader, name string) ([]byte, error) {
	for _, f := range zr.File {
		if f.Name != name {
			continue
		}
		r, err := f.Open()
		if err != nil {
			return nil, fmt.Errorf("part %s: %w", name, err)
		}
		defer r.Close() //nolint:errcheck
		var buf bytes.Buffer
		if _, err := buf.ReadFrom(r); err != nil {
			return nil, fmt.Errorf("part %s: %w", name, err)
		}
		return buf.Bytes(), nil
	}
	return nil, fmt.Errorf("part %s absent", name)
}

func parseM0DeclaredPages(appXML string) (int, error) {
	const open, close = "<Pages>", "</Pages>"
	start := strings.Index(appXML, open)
	if start < 0 {
		return 0, errors.New("m0 corpus: docProps/app.xml has no <Pages> declaration")
	}
	start += len(open)
	end := strings.Index(appXML[start:], close)
	if end < 0 {
		return 0, errors.New("m0 corpus: docProps/app.xml <Pages> is unterminated")
	}
	n, err := strconv.Atoi(strings.TrimSpace(appXML[start : start+end]))
	if err != nil || n <= 0 {
		return 0, fmt.Errorf("m0 corpus: docProps/app.xml <Pages> %q is not a positive page count", appXML[start:start+end])
	}
	return n, nil
}

func isM0SHA256Hex(s string) bool {
	if len(s) != sha256.Size*2 {
		return false
	}
	_, err := hex.DecodeString(s)
	return err == nil && strings.ToLower(s) == s
}
